<section class="page-hero"><div class="mx-auto max-w-content px-5 py-20 lg:px-6 lg:py-28"><p class="eyebrow">Community experiences</p><h1 class="page-title mt-5">Stories shared with care</h1><p class="mt-6 max-w-2xl text-lg leading-8 text-muted">Read experiences from people we have supported, or share your own story for publication.</p></div></section>
<section class="section"><div class="mx-auto grid max-w-content gap-10 px-5 lg:grid-cols-[1.15fr_.85fr] lg:px-6"><div><?php if ($testimonials): ?><div class="grid gap-5 sm:grid-cols-2"><?php foreach ($testimonials as $testimonial): ?><figure class="rounded-[24px] border border-line bg-white p-7 shadow-sm"><blockquote class="font-display text-2xl leading-9 text-wine">“<?= e($testimonial['quote']) ?>”</blockquote><figcaption class="mt-6 flex items-center gap-3"><?php if ($testimonial['photo_path']): ?><img src="<?= e(media_url($testimonial['photo_path'])) ?>" alt="<?= e($testimonial['photo_alt']) ?>" class="size-12 rounded-full object-cover"><?php else: ?><span class="grid size-12 place-items-center rounded-full bg-blush font-bold text-wine"><?= e(mb_substr($testimonial['client_name'], 0, 1)) ?></span><?php endif; ?><span class="font-bold text-wine"><?= e($testimonial['client_name']) ?></span></figcaption></figure><?php endforeach; ?></div><?php else: ?><div class="empty-state">No published testimonials yet.</div><?php endif; ?></div><aside class="self-start rounded-[28px] border border-line bg-white p-6 shadow-soft sm:p-8"><h2 class="font-display text-3xl text-wine">Share your experience</h2><?php if (isset($_GET['sent'])): ?><div class="success-panel mt-6"><p class="font-bold text-wine">Thank you for sharing your story.</p><p class="mt-2 text-sm text-muted"><?= $autoApprove ? 'It is now visible on this page.' : 'An administrator will review it before publication.' ?></p></div><?php elseif ($submissionsEnabled): ?><form method="post" action="<?= e(url('/testimonials')) ?>" class="mt-6 space-y-5"><input type="text" name="website" class="honeypot" tabindex="-1" autocomplete="off" aria-hidden="true"><?= csrf_field() ?><div class="form-field"><label for="testimonial-name">Name or display name <span>*</span></label><input class="form-control" id="testimonial-name" name="client_name" maxlength="190" value="<?= e(old('client_name')) ?>" required></div><div class="form-field"><label for="testimonial-email">Email <span>*</span></label><input class="form-control" type="email" id="testimonial-email" name="email" value="<?= e(old('email')) ?>" required><p class="field-help">Used for administration only; never shown publicly.</p></div><div class="form-field"><label for="testimonial-quote">Your testimonial <span>*</span></label><textarea class="form-control min-h-40" id="testimonial-quote" name="quote" minlength="20" maxlength="1000" required><?= e(old('quote')) ?></textarea></div><label class="consent-row"><input type="checkbox" name="consent" value="1" required><span>I consent to this testimonial and display name being published on the website.</span></label><button class="button button-primary w-full">Submit testimonial</button></form><?php else: ?><p class="mt-4 text-sm leading-6 text-muted">Public submissions are currently paused. Please contact the team if you would like to share feedback.</p><?php endif; ?></aside></div></section>
